#include <stdint.h>


int main(void)
{
    uint32_t *pClckReg = (uint32_t*)0x4002104C;
    uint32_t *portAModReg = (uint32_t*)0x48000000;
    uint32_t *portAWriteReg = (uint32_t*)0x48000014;

    // same as *pClckReg = *pClckReg | 0X01;
    *pClckReg |= 0X01;
    //clear the 5 & 6 bit
    *portAModReg &= ~(3<<10);
    //set 5 to 1
    *portAModReg |= (1<<10);




	while(1){
		*portAWriteReg ^= (1<<5);

		for(volatile uint32_t i = 0; i < 50000; i++);
	};
}
